import os, json, openpyxl
files=[]
for b in ['inputs','.','/mnt/data','data']:
    if os.path.isdir(b):
        for root,_,fs in os.walk(b):
            for f in fs:
                if f.lower().endswith(('.xlsx','.xlsm')):
                    files.append(os.path.join(root,f))
print('FILES', files[:5])
path=files[0]
wf=openpyxl.load_workbook(path, data_only=False)
wv=openpyxl.load_workbook(path, data_only=True)
for ws in wf.worksheets:
    wsv=wv[ws.title]
    print('SHEET', ws.title, 'dims', ws.max_row, ws.max_column)
    for r in range(1, min(ws.max_row,14)+1):
        out=[]
        for c in range(1, ws.max_column+1):
            cf=ws.cell(r,c); cv=wsv.cell(r,c)
            out.append((cf.coordinate, repr(cf.value), cf.data_type, repr(cv.value)))
        print(out)
# relation check
ex={}
for r in range(2,14):
    s=wv['Export'].cell(r,1).value
    ex[r]=(s, wv['Export'].cell(r,3).value)
cnt={wv['Counts'].cell(r,1).value:(wv['Counts'].cell(r,2).value) for r in range(2,14)}
pk={wv['Pack factors'].cell(r,1).value:(wv['Pack factors'].cell(r,2).value) for r in range(2,14)}
for r in range(2,14):
    s,q=ex[r]
    print('ROW', r, repr(s), 'qty=', q, 'cartons=', cnt.get(s), 'ppc=', pk.get(s), 'prod=', (cnt.get(s) or 0)*(pk.get(s) or 0), 'offset=', None if q is None else q-(cnt.get(s) or 0)*(pk.get(s) or 0))
print('keys_equal', list(cnt.keys())==list(pk.keys()), list(ex.values())[0][0]==list(cnt.keys())[0])
print('sample key types', [type(list(cnt.keys())[0]).__name__])
print('MANIFEST', open('inputs/manifest.json').read()[:800] if os.path.exists('inputs/manifest.json') else 'none')

